head.script:
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 sampleCol1 컬럼 셀의 inputType 과 displayFormat 를 확인한다.
    //1. In the Source tab, check the inputType and displayFormat of the sampleCol1 column cell.
    //Verify step 1. inputType="calendar" / displayFormat="yyyy-MM-dd"
    //1. inputType = "calendar" / displayFormat = "yyyy-MM-dd"
    //Test step 2. sampleCol2 컬럼 셀의 inputType 과 displayFormat 를 확인한다.
    //2. Check the inputType and displayFormat of the sampleCol2 column cell.
    //Verify step 2.. inputType="calendar" / displayFormat="yyyy-MM-dd HH:mm:SS"
    //2 .. inputType = "calendar" / displayFormat = "yyyy-MM-dd HH: mm: SS"
    //Test step 3. 브라우저에서 sampleCol1 컬럼의 셀과 sampleCol2 컬럼의 셀을 확인한다.
    //3. In the browser, check the cells in the sampleCol1 column and the cells in the sampleCol2 column.
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. 2015-01-02 / 2015-01-02 12:23:23 (그전에는 2015-01-02 / 20150102122323 로 표시되었음.)
    //3. 2015-01-02 / 2015-01-02 12:23:23 (Previously marked 2015-01-02 / 20150102122323.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').innerText", "2015-01-02");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_2').innerText", "2015-01-02 12:23:23");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 27-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
